>> +static bool check_swapped(int pagemap_fd, char *addr, unsigned long size)
>> +{
>> +	unsigned long off;
>> +
>> +	for (off = 0; off < size; off += getpagesize())
>> +		if (!pagemap_is_swapped(pagemap_fd, addr + off))
>> +			return false;
>> +	return true;
>> +}
