>> +	f = fopen(ZSWAP_ENABLED_PATH, "r");
>> +	if (!f)
>> +		return false;
>> +
>> +	if (fscanf(f, " %c", &enabled) != 1)
>> +		enabled = 0;
>> +	fclose(f);
>> +
>> +	return enabled == 'Y' || enabled == 'y' || enabled == '1';
