>> +
>> +	f = fopen("/proc/vmstat", "r");
>> +	if (!f)
>> +		return 0;
>> +	while (fgets(line, sizeof(line), f)) {
>> +		if (!strncmp(line, name, name_len) && line[name_len] == ' ') {
>> +			val = strtoul(line + name_len + 1, NULL, 10);
>> +			break;
>> +		}
>> +	}
