>+		ASSERT_TRUE(check_huge_anon(self->mem, self->pmd_size, 1,
>+					    self->pmd_size));
>+	if (self->uffd >= 0)
>+		ASSERT_TRUE(expect_rwp_fault(self->uffd, self->mem,
